from bisect import bisect_right


class TimeMap:
    def __init__(self) -> None:
        # Each key's (time, value) entries, in the order they were set, so by time.
        self.history: dict[str, list[tuple[int, str]]] = {}

    def set(self, key: str, value: str, time: int) -> None:
        self.history.setdefault(key, []).append((time, value))

    def get(self, key: str, time: int) -> str:
        entries = self.history.get(key, [])
        # How many entries were set at or before time.
        count = bisect_right(entries, time, key=lambda entry: entry[0])
        return entries[count - 1][1] if count > 0 else "null"


