#include <algorithm>
#include <iostream>
#include <map>
#include <string>
#include <vector>

struct TimedValue {
    int time;
    std::string value;
};

class TimeMap {
public:
    void set(const std::string& key, const std::string& value, int time) {
        history_[key].push_back({time, value});
    }

    std::string get(const std::string& key, int time) const {
        auto found = history_.find(key);
        if (found == history_.end()) {
            return "null";
        }
        const std::vector<TimedValue>& entries = found->second;
        // The first entry set after time. The answer is the one just before it.
        auto after = std::upper_bound(entries.begin(), entries.end(), time,
                                      [](int t, const TimedValue& entry) { return t < entry.time; });
        return after == entries.begin() ? "null" : (after - 1)->value;
    }

private:
    // Each key's entries, in the order they were set, so by time.
    std::map<std::string, std::vector<TimedValue>> history_;
};

int main() {
    int q;
    std::cin >> q;
    TimeMap store;
    for (int i = 0; i < q; i++) {
        std::string op, key, value;
        int time;
        std::cin >> op >> key;
        if (op == "set") {
            std::cin >> value >> time;
            store.set(key, value, time);
        } else {
            std::cin >> time;
            std::cout << store.get(key, time) << "\n";
        }
    }
    return 0;
}

